module agent.page_title
  purpose: Count characters in downloaded page titles for agents.

import std.http as http

public type PageTitleError is one of
  purpose: Why a page title could not be counted.
  DownloadFailed(detail: Text)
  MissingTitle(detail: Text)
end

public function title_character_count(url: http.Url)
  returns Integer
  or fails with PageTitleError
  needs network.http
  purpose: Download a web page and return the number of characters in its title element.
  expose as tool

  let page be http.get(url) otherwise fail with DownloadFailed(detail: "Could not download the page.")
  let title be extract_title(page) otherwise fail with MissingTitle(detail: "The page has no title element.")
  return title.length()
end

function extract_title(page: Text)
  returns maybe Text
  purpose: Read the text inside the first title element.
  example: extract_title(page: "<html><head><title>Hello</title></head></html>") is "Hello"

  let lowered be page.to_lower()
  let open_index be lowered.index_of("<title>") otherwise return nothing
  let after_open be open_index + "<title>".length()
  let rest_lowered be lowered.drop(after_open)
  let close_offset be rest_lowered.index_of("</title>") otherwise return nothing
  let rest_original be page.drop(after_open)
  return rest_original.take(close_offset)
end
