module agents.title_tools
  purpose: Agent tools for reading HTML page titles.

import std.http as http

public type PageTitleError is one of
  purpose: A clear reason the page title length could not be returned.
  DownloadFailed(url: http.Url)
  MissingTitle(url: http.Url)
end

public function title_character_count(url: http.Url)
  returns Integer
  or fails with PageTitleError
  needs network.http
  purpose: Download a web page and return the number of characters in its title element.
  expose as tool

  let page be http.get(url) otherwise fail with DownloadFailed(url: url)
  let count be title_length(page) otherwise fail with MissingTitle(url: url)
  return count
end

function title_length(page: Text)
  returns maybe Integer
  purpose: Return the number of characters between the first title tags in a page.
  example: title_length("<html><title>Hello</title></html>") is 5

  let lower_page be page.to_lower()
  let open_index be lower_page.index_of("<title>") otherwise return nothing
  let after_open be open_index + "<title>".length()
  let remaining_page be page.drop(after_open)
  let remaining_lower_page be lower_page.drop(after_open)
  let close_index be remaining_lower_page.index_of("</title>") otherwise return nothing
  let title_text be remaining_page.take(close_index)
  return title_text.length()
end
